+</style></head><body><div id="scene"></div><div class="shade"></div><header class="top"><div class="brand">Giant <i>Hearts</i></div><div class="world">The quiet coast · your little world</div><div class="topright"><span class="dot"></span><span>WORLD IS YOURS</span></div></header><main class="panel"><section class="intro"><div class="eyebrow">A slow-life giant romance</div><h1>A bigger world<br>to get lost in.</h1><p>Make a life together on the coast. Look after him, explore the landscape, and discover just how small the world can feel.</p></section><section class="card"><div class="row"><div class="name">Luca Moretti</div><span class="tag" id="temper">GENTLE GIANT</span></div><div class="bio">27 · Italian-American · pro rugby · warm-hearted<br>He remembers how you take your coffee.</div><div class="divider"></div><div class="row"><span class="label">His height</span><span class="height" id="height">24 ft</span></div><input id="slider" class="range" type="range" min="7" max="100" value="24"><div class="scale"><span>7 ft</span><span>Choose his scale</span><span>100 ft</span></div><div class="modes"><div class="mode active" data-mode="Gentle">♡ Gentle</div><div class="mode" data-mode="Confident">✦ Confident</div><div class="mode" data-mode="Playful">☼ Playful</div></div><div class="needs"><div class="need"><div class="needtop"><span>Fullness</span><span id="foodval">68%</span></div><div class="bar"><div class="fill warm" id="foodbar" style="width:68%"></div></div></div><div class="need"><div class="needtop"><span>Closeness</span><span id="loveval">42%</span></div><div class="bar"><div class="fill" id="lovebar" style="width:42%"></div></div></div></div></section><section class="actions"><button class="action" data-act="meal"><span class="ico">🥘</span> Make him a meal</button><button class="action" data-act="cuddle"><span class="ico">🫶</span> Ask for a cuddle</button><button class="action" data-act="kiss"><span class="ico">💋</span> Steal a kiss</button><button class="action" data-act="explore"><span class="ico">🧭</span> Explore together</button><button class="action" data-act="compare"><span class="ico">↕</span> Size comparison</button><button class="action" id="sound"><span class="ico">♫</span> Ambient sound</button><button class="action primary" data-act="hangout">Spend the evening together <span>→</span></button></section></main><div class="comp">YOU, NEXT TO LUCA<strong id="comparison">A tiny speck at 24 ft</strong></div><div class="hint">DRAG TO LOOK AROUND &nbsp;·&nbsp; SCROLL TO ZOOM</div><div class="toast" id="toast"></div>
+<script type="module">
+import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';import {OrbitControls} from 'https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/controls/OrbitControls.js';
+const scene=new THREE.Scene();scene.background=new THREE.Color('#b8c6bc');scene.fog=new THREE.Fog('#b8c6bc',55,190);const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,500);camera.position.set(18,13,35);const renderer=new THREE.WebGLRenderer({antialias:true});renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;document.querySelector('#scene').appendChild(renderer.domElement);const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(0,8,0);controls.enableDamping=true;controls.minDistance=12;controls.maxDistance=90;controls.maxPolarAngle=Math.PI*.49;
+scene.add(new THREE.HemisphereLight(0xeaf2ed,0x64735d,2));const sun=new THREE.DirectionalLight(0xffe1bd,3.1);sun.position.set(-24,42,15);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);scene.add(sun);
+const mat=(c,r=.8)=>new THREE.MeshStandardMaterial({color:c,roughness:r});const ground=new THREE.Mesh(new THREE.PlaneGeometry(400,400),mat('#728b72'));ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;scene.add(ground);const water=new THREE.Mesh(new THREE.PlaneGeometry(240,80),new THREE.MeshStandardMaterial({color:'#678f94',roughness:.3,metalness:.15}));water.rotation.x=-Math.PI/2;water.position.set(0,.04,-52);scene.add(water);
+// layered coast and rolling headlands
+for(let i=0;i<13;i++){let m=new THREE.Mesh(new THREE.SphereGeometry(1,12,9),mat(i%3?'#81977a':'#929e7e'));m.position.set(-64+i*11,4+Math.sin(i*1.7)*2,-72-Math.random()*13);m.scale.set(18,9+Math.random()*7,13);m.receiveShadow=true;m.castShadow=true;scene.add(m)}
+// pine trees framing the little coastal path
+function tree(x,z,s){let trunk=new THREE.Mesh(new THREE.CylinderGeometry(.18*s,.28*s,2.2*s,7),mat('#594c3c'));trunk.position.set(x,1.1*s,z);trunk.castShadow=true;scene.add(trunk);for(let j=0;j<3;j++){let c=new THREE.Mesh(new THREE.ConeGeometry((1.4-j*.25)*s,2.8*s,8),mat(j===2?'#58745a':'#3f6552'));c.position.set(x,(2+j*1.15)*s,z);c.castShadow=true;scene.add(c)}}for(let i=0;i<50;i++){const x=(Math.random()-.5)*100,z=12+Math.random()*60;if(Math.abs(x)>14)tree(x,z,.7+Math.random()*.8)}
+// boardwalk, tiny cabin, warm windows
+const path=new THREE.Mesh(new THREE.BoxGeometry(8,.16,80),mat('#ae9272'));path.position.set(0,.08,35);scene.add(path);const cabin=new THREE.Group();const walls=new THREE.Mesh(new THREE.BoxGeometry(7,4.5,6),mat('#ddc6a2'));walls.position.y=2.25;walls.castShadow=true;walls.receiveShadow=true;cabin.add(walls);const roof=new THREE.Mesh(new THREE.ConeGeometry(5.5,3.2,4),mat('#554b43'));roof.rotation.y=Math.PI/4;roof.position.y=6;roof.castShadow=true;cabin.add(roof);const win=new THREE.Mesh(new THREE.BoxGeometry(.12,1.5,1.25),new THREE.MeshStandardMaterial({color:'#f3bd72',emissive:'#bf6e28',emissiveIntensity:1.3}));win.position.set(3.55,2.5,.7);cabin.add(win);cabin.position.set(15,0,25);scene.add(cabin);
+// Luca: athletic, adult, fully clothed. Built from carefully shaded 3D forms.
+const guy=new THREE.Group();scene.add(guy);const skin=mat('#c58f70'),shirt=mat('#d8e0d7'),shorts=mat('#374b49'),shoe=mat('#e8e1d3'),hair=mat('#49382e');function ball(parent,geo,material,pos,scale){const o=new THREE.Mesh(geo,material);o.position.set(...pos);o.scale.set(...scale);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}function limb(a,b,r1,r2,material){const va=new THREE.Vector3(...a),vb=new THREE.Vector3(...b),d=new THREE.Vector3().subVectors(vb,va);const o=new THREE.Mesh(new THREE.CylinderGeometry(r2,r1,d.length(),12),material);o.position.copy(va).add(vb).multiplyScalar(.5);o.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());o.castShadow=true;guy.add(o)}
+ball(guy,new THREE.CylinderGeometry(.47,.58,1.75,16),shorts,[0,1.25,0],[1,1,1]);ball(guy,new THREE.SphereGeometry(1,20,16),shirt,[0,2.8,0],[1.02,1.1,.53]);ball(guy,new THREE.CylinderGeometry(.17,.19,.42,12),skin,[0,3.52,0],[1,1,1]);ball(guy,new THREE.SphereGeometry(1,24,20),skin,[0,4.05,0],[.48,.57,.45]);ball(guy,new THREE.SphereGeometry(1,16,12),hair,[0,4.48,-.02],[.49,.23,.47]);ball(guy,new THREE.SphereGeometry(.19,12,9),hair,[-.49,4.1,0],[.5,1,1]);ball(guy,new THREE.SphereGeometry(.19,12,9),hair,[.49,4.1,0],[.5,1,1]);for(let s of [-1,1]){limb([s*.42,1.05,0],[s*.48,.25,.03],.21,.16,skin);ball(guy,new THREE.BoxGeometry(.47,.2,.75),shoe,[s*.48,.13,.16],[1,1,1]);limb([s*.82,3.18,0],[s*1.05,2.13,.14],.32,.22,shirt);limb([s*1.05,2.13,.14],[s*1.1,1.55,.34],.2,.13,skin);ball(guy,new THREE.SphereGeometry(.18,12,10),skin,[s*1.1,1.48,.36],[.85,1.1,.7])} // face details
+const eye=mat('#302720'),white=mat('#efe6d7');for(let s of [-1,1]){ball(guy,new THREE.SphereGeometry(.055,10,8),white,[s*.17,4.1,.405],[1,1,.6]);ball(guy,new THREE.SphereGeometry(.03,10,8),eye,[s*.17,4.1,.438],[1,1,.6])}const smile=new THREE.Mesh(new THREE.TorusGeometry(.12,.018,6,14,Math.PI),mat('#784f43'));smile.position.set(0,3.88,.43);smile.rotation.z=Math.PI;guy.add(smile);guy.position.set(0,0,1);
+// small scale-reference avatar on the beach
+const you=new THREE.Group();scene.add(you);ball(you,new THREE.CylinderGeometry(.11,.13,.42,9),mat('#c98261'),[0,.35,0],[1,1,1]);ball(you,new THREE.SphereGeometry(.13,10,8),mat('#d6a07e'),[0,.66,0],[1,1,1]);ball(you,new THREE.ConeGeometry(.18,.34,8),mat('#e7c69e'),[0,.47,0],[1,1,1]);you.position.set(2.4,0,4);
+const slider=document.querySelector('#slider');function setHeight(v){document.querySelector('#height').textContent=v+' ft';let k=v/24;guy.scale.set(k,k,k);guy.position.y=0;you.scale.setScalar(Math.min(1,Math.max(.2,24/v)));document.querySelector('#comparison').textContent=v<10?'About twice your height':v<20?'A towering presence':v<40?'A tiny speck at '+v+' ft':v<75?'Barely up to his ankle':'Smaller than his shoe';controls.target.y=Math.max(4,v/4.5);camera.position.y=Math.max(9,v*.56);}
